<?php
declare(strict_types=1);
$paginaAtual = 'rpi';
require __DIR__ . '/rpi_service.php';
function e(string|int|float|null $v): string { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); }
function tamanhoLegivel(int $v): string { return $v < 1048576 ? number_format($v / 1024, 1, ',', '.') . ' KB' : number_format($v / 1048576, 1, ',', '.') . ' MB'; }
$mensagem = ''; $erro = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['acao'] ?? '') === 'sincronizar') {
    try { $edicao = rpiSincronizarEImportarMaisRecente(); $mensagem = 'A RPI ' . $edicao['numero'] . ' foi baixada; ' . $edicao['publicacoes_importadas'] . ' publicações novas foram importadas.'; }
    catch (Throwable $excecao) { $erro = $excecao->getMessage(); }
}
$edicoes = rpiCarregarIndice();
?>
