19px;margin-bottom:5px}.info span{color:var(--muted);font-size:13px}.sub{font-size:18px;margin-bottom:5px}.hint{color:var(--muted);font-size:14px;line-height:1.5;margin-bottom:20px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:14px}.table th{text-align:left;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.4px;padding:12px;border-bottom:1px solid var(--line)}.table td{padding:15px 12px;border-bottom:1px solid var(--line)}.tag{background:#eaf1ff;color:#2452aa;border-radius:999px;padding:5px 9px;font-weight:700;font-size:12px}.link{color:var(--blue);font-weight:700;text-decoration:none}.empty{text-align:center;padding:34px;color:var(--muted)}code{background:#f1f5f9;padding:2px 5px;border-radius:4px;color:#334155}@media(max-width:800px){.layout{grid-template-columns:1fr}aside{display:none}main{padding:24px 18px}.header{display:block}.header form{margin-top:16px}.info{grid-template-columns:1fr}}
</style></head><body><div class="layout"><?php require __DIR__ . '/menu.php'; ?><main><div class="header"><div><h1>Revista RPI</h1><p>Baixe e mantenha arquivadas as edições de Marcas da Revista da Propriedade Industrial.</p></div><form method="post"><input type="hidden" name="acao" value="sincronizar"><button class="button" type="submit">Sincronizar edição mais recente</button></form></div><?php if ($mensagem !== ''): ?><div class="notice success"><?= e($mensagem) ?></div><?php endif; ?><?php if ($erro !== ''): ?><div class="notice error"><?= e($erro) ?></div><?php endif; ?><section class="card"><h2 class="sub">Atualização automática</h2><p class="hint">O INPI publica a RPI semanalmente às terças-feiras. Para automatizar neste computador, crie uma tarefa no Agendador do Windows que execute <code>php sincronizar_rpi.php</code> toda terça após a publicação. O script só baixa a edição caso ela ainda não esteja arquivada.</p><div class="info"><div><strong><?= count($edicoes) ?></strong><span>Edições salvas</span></div><div><strong>Terças-feiras</strong><span>Periodicidade oficial</span></div><div><strong>PDF de Marcas</strong><span>Fonte: portal do INPI</span></div></div><h2 class="sub">Edições baixadas</h2><p class="hint">Na próxima etapa, estas edições serão lidas para localizar automaticamente as publicações dos processos cadastrados.</p><div class="table-wrap"><table class="table"><thead><tr><th>RPI</th><th>Data da publicação</th><th>Arquivo</th><th>Tamanho</th><th></th></tr></thead><tbody><?php if ($edicoes === []): ?><tr><td class="empty" colspan="5">Nenhuma edição baixada ainda. Use o botão de sincronização para buscar a mais recente.</td></tr><?php endif; ?><?php foreach ($edicoes as $edicao): ?><tr><td><span class="tag">RPI <?= e($edicao['numero'] ?? '') ?></span></td><td><?= e($edicao['data'] ?? 'Não informada') ?></td><td><?= e($edicao['arquivo'] ?? '') ?></td><td><?= isset($edicao['tamanho']) ? e(tamanhoLegivel((int) $edicao['tamanho'])) : '—' ?></td><td><?php if (!empty($edicao['arquivo'])): ?><a class="link" target="_blank" href="rpis/<?= rawurlencode((string) $edicao['arquivo']) ?>">Abrir PDF</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></body></html>
